require_once __DIR__.'/../config/auth.php';
$userId=require_roles(['Buyer']);
require_once __DIR__.'/../config/db.php';
function sa_h($v):string{return htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');}
$existing=hb_fetch_one(hb_query($conn,"SELECT * FROM seller_applications WHERE user_id=? ORDER BY id DESC LIMIT 1",[$userId]))?:[];
$account=hb_fetch_one(hb_query($conn,"SELECT username,email FROM users WHERE id=? LIMIT 1",[$userId]))?:[];
