if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();
 try{
  if($existing && $existing['status']==='pending') throw new RuntimeException('Your seller application is already under review.');
  $name=trim((string)($_POST['full_name']??''));$phone=trim((string)($_POST['phone_number']??''));$address=trim((string)($_POST['address']??''));$idType=trim((string)($_POST['id_type']??''));$idNumber=trim((string)($_POST['id_number']??''));
  if($name===''||$phone===''||$address===''||$idType===''||$idNumber==='')throw new RuntimeException('Complete all required details.');
  if(strlen($name)>160||strlen($phone)>30||strlen($address)>255||strlen($idType)>100||strlen($idNumber)>100)throw new RuntimeException('One or more fields are too long.');
  $base=__DIR__.'/../uploads/private/seller-verification';if(!is_dir($base)&&!mkdir($base,0750,true))throw new RuntimeException('Secure upload folder could not be created.');
  $save=function(string $key)use($base):string{$f=$_FILES[$key]??null;if(!$f||($f['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK)throw new RuntimeException('Upload both the ID photo and the selfie holding the same ID.');if(($f['size']??0)>5*1024*1024)throw new RuntimeException('Each image must be 5 MB or smaller.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??null;if(!$ext||!getimagesize($f['tmp_name']))throw new RuntimeException('Upload valid JPG, PNG, or WEBP images only.');$name=bin2hex(random_bytes(18)).'.'.$ext;if(!move_uploaded_file($f['tmp_name'],$base.'/'.$name))throw new RuntimeException('The identity image could not be saved.');return 'uploads/private/seller-verification/'.$name;};
  $front=$save('id_front');$selfie=$save('selfie_with_id');
  hb_query($conn,"INSERT INTO seller_applications(user_id,full_name,phone_number,address,id_type,id_number,id_front_path,selfie_with_id_path,status) VALUES(?,?,?,?,?,?,?,?, 'pending')",[$userId,$name,$phone,$address,$idType,$idNumber,$front,$selfie]);
  hb_query($conn,"INSERT INTO activity_logs(user_id,action,entity_type,record_id,ip_address) VALUES(?,?,?,?,?)",[$userId,'Submitted seller application','seller_application',(int)mysqli_insert_id($conn),$_SERVER['REMOTE_ADDR']??null]);
  $existing=hb_fetch_one(hb_query($conn,"SELECT * FROM seller_applications WHERE user_id=? ORDER BY id DESC LIMIT 1",[$userId]))?:[];$notice='Your application was submitted. You can continue using your Buyer account while it is reviewed.';
 }catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'The application could not be submitted. Please try again.';if(!$e instanceof RuntimeException)error_log('Seller application: '.$e->getMessage());}
}
